def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        first = row[0]
        k = 1
        while k < len(row) and row[k] == first:
            k += 1
        if k < len(row) and all(x == row[k] for x in row[k:]):
            for j in range(k, len(row)):
                out[r][j] = 1
    return out
